from django import template
from django.template.base import token_kwargs
from djinn.core.cva import cva

register = template.Library()

input_cva = cva(
    base="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background file:border-0 file:bg-transparent file:text-sm file:font-medium placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-50",
    variants={
        "variant": {
            "default": "",
            "error": "border-destructive",
        },
    },
    default_variants={
        "variant": "default",
    }
)

class InputNode(template.Node):
    def __init__(self, nodelist, kwargs):
        self.nodelist = nodelist
        self.kwargs = kwargs

    def render(self, context):
        resolved_kwargs = {}
        for k, v in self.kwargs.items():
            try:
                resolved_kwargs[k] = v.resolve(context)
            except template.VariableDoesNotExist:
                resolved_kwargs[k] = ""

        # Evaluate cva
        final_class = input_cva(**resolved_kwargs)

        # Separate extra attributes
        known_args = ["variant", "label", "placeholder", "error", "help_text", "type", "name", "id", "value", "disabled", "required", "class", "class_name"]
        attrs = {k: v for k, v in resolved_kwargs.items() if k not in known_args}

        t = context.template.engine.get_template('components/input.html')
        new_context = context.new({
            "class": final_class,
            "attrs": attrs,
            **resolved_kwargs
        })
        return t.render(new_context)

@register.tag('djinn_input')
def djinn_input(parser, token):
    bits = token.split_contents()
    kwargs = token_kwargs(bits[1:], parser)
    nodelist = parser.parse(('enddjinn_input',))
    parser.delete_first_token()
    return InputNode(nodelist, kwargs)
